"""Publish the reusable full finite-model response study and replay package."""
from fractions import Fraction as F
import hashlib
import html
import json
from chemistry_responses_data import DATA,AREA,build as build_data,replay

PAGE='chemistry-responses.html'

def number(value):return f'{float(F(value)):.6g}'
def table(caption,head,rows):
    return '<div class="cr-table" tabindex="0" role="group" aria-label="'+html.escape(caption)+'; scroll horizontally if needed"><table><caption>'+caption+'</caption><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<'+('th scope="row"' if i==0 else 'td')+'>'+str(v)+'</'+('th' if i==0 else 'td')+'>' for i,v in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'

def build(site):
    raw=(site.root/DATA).read_bytes();data=json.loads(raw)
    if raw!=(json.dumps(build_data(site.root),separators=(',',':'))+'\n').encode():raise ValueError('Stale response fixtures')
    digest=hashlib.sha256(raw).hexdigest()
    def asset(name,content=None):
        payload=content if content is not None else (site.root/'website/assets'/name).read_bytes()
        return 'assets/'+name+'?v='+hashlib.sha256(payload).hexdigest()[:12]
    site.write('assets/chemistry/responses-v1.json',raw.decode())
    for name in ['chemistry-responses.css','chemistry-responses-core.mjs']:
        site.write('assets/'+name,(site.root/'website/assets'/name).read_text(encoding='utf-8'))
    script=(site.root/'website/assets/chemistry-responses.js').read_text(encoding='utf-8').replace("'./chemistry-responses-core.mjs'","'./"+asset('chemistry-responses-core.mjs').removeprefix('assets/')+"'")
    site.write('assets/chemistry-responses.js',script)
    package=replay(site.root);target=site.output/'assets/chemistry/stage15-replay.zip';target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(package)
    for name in ['RESPONSE_CERTIFICATES.md','SELF_REVIEW.json','inputs/INPUT_VIEW.json']:
        site.write('assets/chemistry/stage15/'+name,(site.root/AREA/name).read_text(encoding='utf-8'))
    summaries=table('Largest response radius across the 41 sampled energies, per Hartree',['Full-target actions','η = 0.01','η = 0.1','η = 0.5'],[[str(k)]+[number(max(p['max_radius'] for p in data['summary'] if p['method']=='polynomial-krylov' and p['actions']==k and p['eta']==eta)) for eta in data['etas']] for k in data['orders']])
    nine=table('Same budget: nine full-target actions, maximum radius per Hartree',['Trial space','η = 0.01','η = 0.1','η = 0.5'],[[label]+[number(max(p['max_radius'] if 'max_radius' in p else p['radius_decimal'] for p in data['summary'] if p['method']==method and p['actions']==9 and p['eta']==eta)) for eta in data['etas']] for method,label in [('occupation-nine','Nine determinants'),('polynomial-krylov','Source-adapted Krylov')]])
    hierarchy=table('Source capture in nested occupation spaces',['Frozen spatial orbitals','Active orbitals','Determinants','Source weight retained'],[[x['frozen_spatial_orbitals'],str(x['active_end_exclusive']-x['frozen_spatial_orbitals']),f"{x['dimension']:,}",f"{100*x['retained_fraction']:.3f}%"] for x in data['source']['hierarchy']])
    timing=data['timings'];times=table('One recorded Windows NumPy run, seconds',['Trial space','H actions','Setup including actions','Scan and certificates'],[['Nine determinants',f"{timing['occupation_oracle_seconds']:.3f}",f"{timing['occupation_total_setup_seconds']:.3f}",f"{timing['occupation_postprocessing_seconds']:.3f}"]]+[[f"Krylov {x['order']}",f"{x['oracle_seconds']:.3f}",f"{x['total_setup_seconds']:.3f}",f"{x['postprocessing_seconds']:.3f}"] for x in timing['krylov']])
    static=table('Response samples: η = 0.1 Hartree, 128-action cache',['Removal coordinate ω, Ha','−Im(g), per Ha','Radius upper bound, per Ha','Reduced-model discrepancy lower bound, per Ha'],[[number(p['omega']),number(-F(p['center']['imaginary'])),number(p['radius']),number(p['imaginary_discrepancy_lower'])] for p in data['points'] if p['eta']=='1/10' and p['actions']==128 and p['method']=='polynomial-krylov'])
    body='''<link rel="stylesheet" href="'''+asset('chemistry-responses.css')+'''">
<div class="cr-page" id="chemistry-responses" data-source="'''+asset('chemistry/responses-v1.json')+'''" data-sha256="'''+digest+'''">
<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Home</a> / <a href="collection/COMPUTATIONAL_CHEMISTRY.html">Computational chemistry</a></nav>
<header class="cr-hero"><p class="cr-eyebrow">From recovery to a useful response</p><h1>One cache.<br><em>An energy scan.</em></h1><p class="cr-lead">Calculate responses at many energies from the same Hamiltonian actions, with an error bound at every sample.</p><p>This H10-derived finite-model study tests what survives beyond the nine-state recovery theorem. Compare a small occupation space with a source-adapted Krylov calculation on the same 52,920-state operator.</p><div class="cr-stats"><div><strong>52,920</strong><span>full-target determinants</span></div><div><strong>41</strong><span>sampled energies per broadening</span></div><div><strong>0</strong><span>extra H actions per energy</span></div></div><nav class="cr-route" aria-label="Response study route"><a href="#cr-scan">Explore the scan</a><a href="#cr-reduction">Check the reduction</a><a href="#cr-evidence">Replay the calculation</a><a href="chemistry-lab.html">Three-query laboratory</a></nav></header>
<section class="cr-panel" id="cr-scan"><p class="cr-eyebrow">01 / Reuse the expensive information</p><h2>How much calculation does this response need?</h2><p>A Hamiltonian action applies the operator H to a vector. The cache stores information from those actions for reuse across the scan.</p><p>Each cache is reused at all 41 sampled energies and all three broadening values. The Krylov trial space is built from the supplied removal source. Smaller broadening resolves finer energy features and can require more actions.</p><p id="cr-status" role="status">Loading the controls and verifying the data identity. The recorded results below are available now.</p><button id="cr-retry" type="button" hidden>Retry loading the scan</button><noscript><p>Read the results and sample table below, or download the replay. Interactive controls require JavaScript.</p></noscript>
<div id="cr-explorer" hidden><div class="cr-controls"><div><label for="cr-eta">Broadening η (Hartree)</label><select id="cr-eta"><option value="1/100">0.01 — finer features</option><option value="1/10" selected>0.1</option><option value="1/2">0.5 — broader features</option></select></div><div><label for="cr-order">Full-target actions in the Krylov cache</label><select id="cr-order">'''+''.join('<option'+(' selected' if k==128 else '')+'>'+str(k)+'</option>' for k in data['orders'])+'''</select></div></div>
<figure class="cr-figure"><figcaption>Local-removal response strength −Im(g), per Hartree</figcaption><div id="cr-plot"></div><p class="cr-legend"><span class="cr-full">● Full finite-model response estimate</span><span class="cr-reduced">◆ Nine-state response estimate</span></p><p id="cr-plot-note"></p></figure>
<label for="cr-energy">Inspect an energy sample <output id="cr-energy-value" for="cr-energy"></output></label><input type="range" id="cr-energy" min="0" max="40" value="20" step="1"><div class="cr-result" id="cr-result" aria-live="polite" aria-atomic="true"></div><dl id="cr-values" class="cr-values"></dl><p id="cr-discrepancy"></p><div class="cr-actions"><button id="cr-download" type="button">Download sample certificate</button><a id="cr-link" href="chemistry-responses.html">Link to this sample</a><button id="cr-reset" type="button">Reset scan</button></div><details><summary>Inspect the sample certificate</summary><pre id="cr-certificate" tabindex="0" role="group" aria-label="Sample certificate; scroll horizontally if needed"></pre></details></div>
<h3>What the recorded scan accomplishes</h3><p>At η = 0.1 Hartree, 128 actions give a response radius below 4 × 10⁻⁹ per Hartree at each of the 41 samples. Those same actions serve the entire scan. At η = 0.01, some enclosures remain wide even after 256 actions. More actions can also raise the rounding floor.</p>'''+summaries+'''<p>These are pointwise bounds on a fixed finite model, conditional on the stated binary64 arithmetic model and checked range guards. Connecting lines interpolate the centers visually; they do not certify the intervening energies.</p><details><summary>Read all 41 samples without the controls</summary>'''+static+'''</details></section>
<section class="cr-panel" id="cr-reduction"><p class="cr-eyebrow">02 / Test the small model</p><h2>Recovering a model is one question.<br>Choosing enough states is another.</h2><p>The original theorem recovers the specified nine-state Hamiltonian from three complete reduced-model actions. For this supplied full-model source, those nine determinants retain <strong>37.506% of the source weight</strong>. Exact full-target columns measure the omitted source and coupling.</p><p>The small model can have an extremely small numerical error while disagreeing with the full finite-model response. At η = 0.1 Hartree, the 128-action calculation certifies a nonzero discrepancy at all 41 samples: the two imaginary-response intervals are disjoint. The explorer shows the discrepancy lower bound at each sample.</p>'''+hierarchy+'''<h3>Compare equal action budgets</h3><p>Here both methods spend nine actions of the same full Hamiltonian, use the same source, and reuse the cache over the same grid. The source-adapted space gives tighter enclosures in this test. A wide upper bound alone does not prove a large actual error.</p>'''+nine+'''<p class="cr-callout">Three reduced-model actions do not recover the 52,920-state Hamiltonian or its omitted-space coupling. The full-target columns in this study provide additional information.</p></section>
<section class="cr-panel" id="cr-evidence"><p class="cr-eyebrow">03 / Keep the assumptions with the answer</p><h2>A result you can inspect and replay.</h2><p>The target is a real, symmetry-completed electronic ion Hamiltonian built from the stored H10 fixture. The supplied approximate local-removal vector is treated as exact input bits. The supplied approximate neutral energy fixes the energy coordinate. These certificates do not cover error in that neutral state, the finite basis, or an experimental prediction.</p><details><summary>Read the residual bound</summary><p>For real symmetric H, real b, z = E + iη with η &gt; 0, and any approximate solution x, set r = b − (zI − H)x. Transpose symmetry gives</p><pre tabindex="0" role="group" aria-label="Residual identity; scroll horizontally if needed">g − bᵀx = xᵀr + rᵀ(zI − H)⁻¹r
|g − bᵀx| ≤ |xᵀr| + ‖r‖² / η</pre><p>The first term vanishes for an exact Galerkin solve in a real trial space. The floating-point calculation retains it and encloses action, multiplication, dot-product, residual-formation, and energy-rounding errors. No exact orthogonality or exact projected solve is assumed.</p><p><a href="assets/chemistry/stage15/RESPONSE_CERTIFICATES.md">Read the full derivation and replay instructions</a> · <a href="assets/chemistry/stage15/SELF_REVIEW.json">Read the author’s proof self-review</a></p></details>
<details><summary>Inspect timing and comparison limits</summary><p>These timings come from one Windows run using NumPy 2.3.5, with the environment configured to request one thread. Shared setup for the inputs, coefficients, and kernel took '''+f"{timing['shared_input_coefficients_and_kernel_setup_seconds']:.3f}"+''' seconds. Postprocessing includes the projected solves and certificates for all 123 combinations of energy and broadening.</p>'''+times+'''<p>The Krylov implementation uses two reorthogonalization passes and stores its action images. It is a polynomial Krylov benchmark, with no claim to outperform an optimized rational, block, or PySCF solver. Action count and wall time are separate measurements.</p></details>
<p>The finite audit checks 73 small-model columns, four independent spin-free operator identities, 32 exact response inclusions, and nine full-target columns against exact sparse references. This supports the implementation; it is distinct from the analytic proof and from independent review.</p><div class="cr-actions"><a href="assets/chemistry/stage15-replay.zip" download>Download the complete response replay</a><a href="assets/chemistry/responses-v1.json">Inspect the public response data</a><a href="assets/chemistry/stage15/inputs/INPUT_VIEW.json">Inspect input identities</a></div><p class="cr-small">Replay SHA-256: <code class="cr-hash">'''+hashlib.sha256(package).hexdigest()+'''</code><br>Response-data SHA-256: <code class="cr-hash">'''+digest+'''</code></p><p>Public response radii are rounded outward to 18 decimal places. The replay retains the original rational bounds and three execution manifests with input and output hashes. The arithmetic enclosure assumes correctly rounded binary64 dot/add operations; this assumption is explicit and has not been established by formal hardware verification.</p><p>For established Lanczos error-bound methods, see <a href="https://arxiv.org/abs/2106.09806v2">Chen, Greenbaum, Musco, and Musco</a>. This study makes no novelty claim.</p><nav class="cr-route" aria-label="Continue studying computational chemistry"><a href="chemistry-lab.html">Recovery experiment</a><a href="read/computational-chemistry/model-error.html">Physical model-error obligations</a><a href="read/computational-chemistry/reproduce.html">Earlier checkpoint and archives</a></nav></section>
<details class="cr-panel"><summary>Keyboard and reading help</summary><p>Tab moves between controls. Use the arrow keys to change the selected options and energy sample. The sample link includes the current settings so you can return to the same sample. The certificate download retains its data identity and assumptions. Graphs have a text description and a sample readout. Tables and certificate blocks can be focused and scrolled with arrow keys. Static results and the full sample table remain available without JavaScript.</p><p>No data are uploaded. This is a recorded calculation explorer, not a molecular simulation running in your browser.</p></details></div><script type="module" src="'''+asset('chemistry-responses.js',script.encode())+'''"></script>'''
    from chemistry_continuous import add as add_continuous
    body,continuous=add_continuous(site,body)
    site.page(PAGE,'Computational chemistry: reusable response scans',body,'https://github.com/KomorebiP/Operation-KOMOREBI/blob/'+site.revision+'/research/computational-chemistry/stage15/RESPONSE_CERTIFICATES.md')
    site.search.append(dict(title='Computational chemistry: reusable response scans',group='Collection',kind='Examples',work_ids=[],url=PAGE,text='H10 52920 determinants reusable Hamiltonian actions source Krylov Lanczos response energy scan residual certificate error bounds finite model nine states coupling leakage practical computational chemistry'))
    return dict(samples=len(data['points']),data_sha256=digest,replay_sha256=hashlib.sha256(package).hexdigest(),replay_bytes=len(package),physical_accuracy_claim=False,continuous=continuous)
